    18→/**
    19→ * Displays telemetry and pilot approval status.
    20→ *
    21→ * <p>Telemetry is mandatory for pilot program participation and cannot be disabled.
    22→ * This command provides transparency into what data is sent and the current
    23→ * approval status.
    24→ *
    25→ * <pre>
    26→ *   synthesis telemetry                     Show status and approval
    27→ *   synthesis telemetry --show              Show what data is sent
    28→ *   synthesis telemetry --check-approval    Force refresh of approval status
    29→ *   synthesis telemetry --reset-uuid        Generate a new client UUID
    30→ * </pre>
    31→ */
    32→@Command(
    33→        name = "telemetry",
    34→        description = "View pilot telemetry and approval status",
    35→        mixinStandardHelpOptions = true
    36→)
    37→public class TelemetryCommand implements Callable<Integer> {
    38→
    39→    @ParentCommand
    40→    private SynthesisApp parent;
    41→
    42→    @Option(
    43→            names = {"--show"},
    44→            description = "Show what data telemetry sends",
