   106→        }
   107→
   108→        AnsiOutput.printHeader("Synthesis - Checking Pilot Approval");
   109→        System.out.printf("  Client UUID: %s%n", uuid);
   110→        System.out.println("  Checking approval channel...");
   111→
   112→        ApprovalService approval = ApprovalService.create();
   113→        try {
   114→            approval.refreshApprovalStatus(uuid);
