   138→    private Path workspaceRoot;
   139→
   140→    /**
   141→     * Returns the resolved workspace root directory.
   142→     * Used by subcommands via @ParentCommand injection.
   143→     *
   144→     * <p>Resolution order:
   145→     * <ol>
   146→     *   <li>Explicit -d/--directory flag (if provided)</li>
   147→     *   <li>SYNTHESIS_WORKSPACE environment variable</li>
   148→     *   <li>~/.synthesis/workspace file</li>
   149→     *   <li>Current directory (fallback)</li>
   150→     * </ol>
   151→     */
   152→    public Path getWorkspaceRoot() {
   153→        // If explicitly provided via -d flag, use that
   154→        if (workspaceRoot != null) {
   155→            return workspaceRoot.toAbsolutePath().normalize();
   156→        }
   157→
   158→        // Try environment variable
   159→        String envWorkspace = System.getenv("SYNTHESIS_WORKSPACE");
   160→        if (envWorkspace != null && !envWorkspace.isBlank()) {
   161→            return Path.of(envWorkspace).toAbsolutePath().normalize();
   162→        }
   163→
   164→        // Try ~/.synthesis/workspace file
   165→        Path workspaceFile = Path.of(System.getProperty("user.home"), ".synthesis", "workspace");
   166→        if (Files.exists(workspaceFile)) {
   167→            try {
   168→                String configuredWorkspace = Files.readString(workspaceFile).trim();
   169→                if (!configuredWorkspace.isEmpty()) {
   170→                    return Path.of(configuredWorkspace).toAbsolutePath().normalize();
   171→                }
   172→            } catch (Exception e) {
   173→                // Ignore and fall through to default
   174→            }
   175→        }
   176→
   177→        // Fall back to current directory
   178→        return Path.of(".").toAbsolutePath().normalize();
   179→    }
